import { describe, expect, it } from "vitest";
import reference from "@shift/types/fixtures/geometry_reference.json";
import { Mat, type DecomposedTransform, type MatModel, type Point2D } from "@shift/geo";
import { angleBetween } from "./testing";

interface ComposeCase {
  readonly name: string;
  readonly decomposed: DecomposedTransform;
  readonly matrix: MatModel;
  readonly point: Point2D;
  readonly mappedPoint: Point2D;
}

interface DecomposeCase {
  readonly name: string;
  readonly matrix: MatModel;
  readonly decomposed: DecomposedTransform;
}

// Generated by `crates/shift-wire/tests/geometry_reference.rs`.
const composeCases = reference.compose as ComposeCase[];
const decomposeCases = reference.decompose as DecomposeCase[];

const DIGITS = 9;

function expectMatrix(actual: MatModel, expected: MatModel): void {
  for (const key of ["a", "b", "c", "d", "e", "f"] as const) {
    expect(actual[key], key).toBeCloseTo(expected[key], DIGITS);
  }
}

describe("component matrices match shift-font's DecomposedTransform", () => {
  it.each(composeCases)("composes $name like to_matrix", ({ decomposed, matrix }) => {
    expectMatrix(Mat.fromDecomposed(decomposed), matrix);
  });

  it.each(composeCases)("maps a point through $name like transform_point", (testCase) => {
    const mapped = Mat.applyToPoint(Mat.fromDecomposed(testCase.decomposed), testCase.point);

    expect(mapped.x).toBeCloseTo(testCase.mappedPoint.x, DIGITS);
    expect(mapped.y).toBeCloseTo(testCase.mappedPoint.y, DIGITS);
  });

  it.each(decomposeCases)("decomposes $name like from_matrix", ({ matrix, decomposed }) => {
    const { rotation, ...actual } = Mat.toDecomposed(matrix);
    const { rotation: expectedRotation, ...expected } = decomposed;

    expect(angleBetween(rotation, expectedRotation)).toBeCloseTo(0, DIGITS);
    for (const [key, value] of Object.entries(expected)) {
      expect(actual[key as keyof typeof actual], key).toBeCloseTo(value, DIGITS);
    }
  });
});
